import os
import time
import hmac
import hashlib
import secrets
import json
import tempfile
from pathlib import Path
from flask import Flask, request, jsonify, g
import fcntl

app = Flask(__name__)
app.config['SESSION_DIR'] = '/tmp/sessions'
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', secrets.token_hex(32))
app.config['SESSION_TTL'] = 3600

def constant_time_compare(a, b):
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def compute_session_mac(session_id, data):
    """Compute HMAC for session integrity verification"""
    key = app.config['SECRET_KEY'].encode()
    msg = f"{session_id}:{json.dumps(data, sort_keys=True)}".encode()
    return hmac.new(key, msg, hashlib.sha256).hexdigest()

def get_session_path(session_id):
    """Get filesystem path for session, with directory traversal protection"""
    if not session_id or not session_id.isalnum():
        return None
    safe_id = session_id[:64]  # Limit length
    session_dir = Path(app.config['SESSION_DIR']).resolve()
    session_path = (session_dir / f"sess_{safe_id}").resolve()
    # Verify path is within session directory
    if not str(session_path).startswith(str(session_dir)):
        return None
    return session_path

def create_session_dir():
    """Ensure session directory exists with proper permissions"""
    session_dir = Path(app.config['SESSION_DIR'])
    session_dir.mkdir(mode=0o700, parents=True, exist_ok=True)

def validate_session_file(path):
    """Check session file is a regular file and owned by us"""
    try:
        stat = os.stat(str(path))
        # Must be regular file
        if not os.path.isfile(str(path)):
            return False
        # Must be owned by current user
        if stat.st_uid != os.getuid():
            return False
        return True
    except OSError:
        return False

def read_session(session_id):
    """Read and validate session data from filesystem"""
    path = get_session_path(session_id)
    if path is None:
        return None

    # Validate the file before reading
    if not validate_session_file(path):
        return None

    # TOCTOU gap: file could be replaced between validate and open
    try:
        with open(str(path), 'r') as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_SH)
            content = f.read()
            fcntl.flock(f.fileno(), fcntl.LOCK_UN)

        data = json.loads(content)

        # Verify session hasn't expired
        if time.time() - data.get('created_at', 0) > app.config['SESSION_TTL']:
            os.unlink(str(path))
            return None

        # Verify HMAC integrity
        stored_mac = data.get('_mac', '')
        computed_mac = compute_session_mac(session_id, {
            k: v for k, v in data.items() if k != '_mac'
        })
        if not constant_time_compare(stored_mac, computed_mac):
            return None

        return data
    except (json.JSONDecodeError, OSError, IOError):
        return None

def write_session(session_id, data):
    """Write session data atomically"""
    path = get_session_path(session_id)
    if path is None:
        return False

    create_session_dir()

    # Add MAC for integrity
    session_data = dict(data)
    session_data['_mac'] = compute_session_mac(session_id, data)

    # Check if session file already exists
    # If it does, we update it; if not, we create it
    if os.path.exists(str(path)):
        if not validate_session_file(path):
            return False

    # TOCTOU gap: between exists check and open, attacker can create symlink
    try:
        with open(str(path), 'w') as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_EX)
            f.write(json.dumps(session_data))
            f.flush()
            os.fsync(f.fileno())
            fcntl.flock(f.fileno(), fcntl.LOCK_UN)
        os.chmod(str(path), 0o600)
        return True
    except OSError:
        return False

@app.before_request
def load_session():
    """Load session from cookie"""
    g.session = None
    g.session_id = None
    session_id = request.cookies.get('session_id')
    if session_id:
        data = read_session(session_id)
        if data:
            g.session = data
            g.session_id = session_id

@app.route('/login', methods=['POST'])
def login():
