@app.route('/api/elevate', methods=['POST'])
def elevate_session():
    """Elevate session privileges (for testing session integrity)"""
    if not g.session:
        return jsonify({'error': 'Unauthorized'}), 401

    # Re-verify credentials for elevation
    password = request.json.get('password', '')
    if not authenticate_user(g.session['user'], password):
        return jsonify({'error': 'Invalid credentials'}), 401

    # Update session with elevated role
    updated_data = dict(g.session)
    updated_data['role'] = 'admin'
    updated_data['elevated_at'] = time.time()
    # Remove old MAC before recomputing
    updated_data.pop('_mac', None)

    if not write_session(g.session_id, updated_data):
        return jsonify({'error': 'Session update failed'}), 500

    return jsonify({'status': 'elevated'})

